-- Брендбук: разделы продуктов.
--
-- Один брендбук, а не три. Общего у продуктов больше, чем различий: знак,
-- шрифты, сетка, отступы, иконки и тон — одни на всех. Различается акцент
-- и несколько продуктовых элементов. Три отдельных документа разошлись бы:
-- правку внесли бы в один и забыли про остальные.

insert into public.brand (id, title, kind, sort, section, data) values

('core-vs-product', 'Ядро и продукты: что можно менять', 'text', 26, 'Правила', jsonb_build_object(
  'body', E'Брендбук один. Общая часть — это ядро: знак, цвет, шрифт и текст, элементы, материалы, правила. Продукты идут после неё отдельными разделами.\n\nГлавное правило\nПродукт может добавлять, но не переопределять ядро.\n\nЧто продукт добавляет своё\n— Акцентный цвет и его градиент\n— Свечение и заливки на крупных плашках\n— Примеры своих экранов\n— Тон обращения к своей аудитории\n\nЧто берётся из ядра и в продукте не меняется\n— Знак и охранное поле\n— Шрифты и размеры\n— Сетка и шкала отступов\n— Иконки и их толщина штриха\n— Состояния: успех, ошибка, выключено\n\nЕсли продукту понадобился другой шрифт заголовков — это не правка в разделе продукта, а разговор про ядро. Иначе через год общая часть станет формальностью.')),

('p-studio', 'Studio: акцент в деле', 'figure', 10, 'ADERVIS Studio', jsonb_build_object(
  'figure', 'product', 'dir', 'Студия', 'product', 'ADERVIS Studio',
  'body', E'Фирменное золото #f6bd3a. Основное направление, поэтому его акцент совпадает с цветом бренда.\n\n— Золото остаётся акцентом, а не фоном: крупные плашки только в заставках\n— На светлом берём тёмный вариант #a87908, иначе не хватает контраста\n— У услуг внутри студии свои цвета: видео, дизайн, фото, ИИ-контент')),

('p-crm', 'CRM: акцент в деле', 'figure', 10, 'ADERVIS CRM', jsonb_build_object(
  'figure', 'product', 'dir', 'CRM', 'product', 'ADERVIS CRM',
  'body', E'Градиент #6c00ff → #9b4dff со свечением. Значения взяты из оформления самого продукта, а не подобраны заново.\n\n— Градиент только на крупных плашках: в мелочи превращается в грязь\n— Свечение — один акцент на экран, не на каждой карточке\n— На светлом фоне берём тёмный конец #6c00ff')),

('p-stock', 'Stock: акцент в деле', 'figure', 10, 'ADERVIS Stock', jsonb_build_object(
  'figure', 'product', 'dir', 'Stock', 'product', 'ADERVIS Stock',
  'body', E'Зелёный #87e64b с тёмным вариантом #6bb23e. Взят из портала PremiumStok.\n\n— На светлом фоне только тёмный вариант #3f7a1c: светло-зелёный на белом не читается\n— Зелёный здесь не значит «успех»: это цвет продукта, состояния берутся из ядра\n— Рядом с золотом держим дистанцию: два ярких акцента в одном макете спорят'))

on conflict (id) do nothing;
